-- zh-TW 공식 계정(pinwith_zhtw)·예시 계정·예시 리스트 4개. 먼저 seed_lang_loader.sql을 실행해 둘 것.
select private.seed_lang_examples('zh-TW', 'zhtw', $doc${"official":{"display_name":"PinWith 官方","bio":"PinWith 團隊精選的在地清單，打開地圖就能照著走。"},"samples":[{"display_name":"範例使用者1","bio":"這是 PinWith 建立的範例帳號，用來示範朋友們如何一起規劃旅行。"},{"display_name":"範例使用者2","bio":"這是 PinWith 建立的範例帳號，用來示範朋友們如何一起規劃旅行。"},{"display_name":"範例使用者3","bio":"這是 PinWith 建立的範例帳號，用來示範朋友們如何一起規劃旅行。"}],"lists":[{"role":"plain","owner":"official","slug":"taipei-dadaocheng-classic-walk","kind":"course","title":"大稻埕老城散步＋台北經典一日","desc":"從迪化街的百年街屋走到淡水河畔看夕陽，晚上再到台北101收尾。不趕行程、搭捷運就能完成的台北入門路線。","themes":["台北","大稻埕","老街散步","夕陽","捷運可達"],"sections":[{"name":"上午｜迪化街與廟宇","by":"official","items":[{"place_id":"ChIJeXELiROpQjQR1REJMdOO8Xo","title":"迪化街","memo":"從南街一路往北逛，南北貨、中藥行和布行都在這段。年貨大街期間人潮很多，平日上午最好逛。","tags":["老街","南北貨"],"lat":25.055102,"lng":121.509983},{"place_id":"ChIJ58RTchSpQjQR0nPhT8U-bWk","title":"霞海城隍廟","memo":"以求姻緣的月下老人聞名，廟不大但香火很旺。參拜時跟著廟方的流程卡走就不會漏步驟。","tags":["廟宇","月老"],"lat":25.055594,"lng":121.510217},{"place_id":"ChIJlSKXuxWpQjQRKJSKn23XVJQ","title":"大稻埕公園","memo":"逛完迪化街中段可以在這裡歇腳，旁邊巷子裡藏著不少老字號小吃。","tags":["休息","公園"],"lat":25.05861,"lng":121.510346}]},{"name":"下午｜老屋與河岸","by":"official","items":[{"place_id":"ChIJZbPRZD6pQjQRq-z3BgGb65k","title":"十連棟","memo":"迪化街北段一整排相連的老街屋，是很多人沒走到的安靜區段，適合拍建築立面。","tags":["老屋","拍照"],"lat":25.062761,"lng":121.509193},{"place_id":"ChIJx4IVtBapQjQRSP3RxLSLdg0","title":"大稻埕碼頭","memo":"傍晚來看淡水河夕陽，碼頭邊的貨櫃市集有飲料和小吃。夏天河岸蚊子多，記得帶防蚊液。","tags":["夕陽","河岸"],"lat":25.056803,"lng":121.507778}]},{"name":"晚上｜信義區收尾","by":"official","items":[{"place_id":"ChIJh8s4AuGrQjQRIw2M8SmpDIw","title":"台北101","memo":"從大稻埕搭捷運就能到。想拍101全景可以走到信義區周邊的步道或廣場，不一定要上觀景台。","tags":["地標","夜景"],"lat":25.033228,"lng":121.564868}]}],"comments":[]},{"role":"creator","owner":"official","slug":"vlog-pingxi-shifen-jiufen-day-trip","kind":"course","title":"[Vlog] 平溪線瀑布＋十分天燈＋九份夜景一日遊","desc":"影片裡走的路線整理在這！早上搭平溪線追瀑布、中午在十分放天燈，傍晚轉去九份等燈籠亮起來。附上每一站的拍攝時間和機位小撇步。","themes":["Vlog","平溪線","九份","瀑布","天燈"],"sections":[{"name":"上午｜平溪線追瀑布","by":"official","items":[{"place_id":"ChIJgeh2i3lQXTQRbfVR2dt5jhQ","title":"摩天瀑布（三貂嶺瀑布步道）","memo":"影片開頭那段水霧就是在這拍的！步道有濕滑的岩石和階梯，一定要穿防滑鞋，出發前先查步道是否開放。","tags":["瀑布","步道","早上拍"],"lat":25.063213,"lng":121.80543},{"place_id":"ChIJ-VY3hjRRXTQRiLphc8yT1-0","title":"嶺腳瀑布","memo":"從嶺腳車站走一小段就到，人比十分少很多，空拍和慢動作鏡頭都很好收。平溪線班次不多，先抓好回程時間。","tags":["瀑布","人少"],"lat":25.028131,"lng":121.74864}]},{"name":"中午｜十分","by":"official","items":[{"place_id":"ChIJ8Z5my_JQXTQRSSmYoOP3EbA","title":"十分瀑布","memo":"台灣最寬的簾幕式瀑布之一，晴天上午容易看到彩虹。我在影片 4:10 那個角度是在觀瀑台左側拍的。","tags":["瀑布","彩虹"],"lat":25.048961,"lng":121.787451},{"place_id":"ChIJp1H8k-1QXTQRz8GHLVzQIVI","title":"十分瀑布步道","memo":"沿著基隆河走到瀑布，途中的吊橋很適合拍走路的 B-roll。雨後步道會濕滑，腳步放慢。","tags":["步道","吊橋"],"lat":25.047575,"lng":121.783985},{"place_id":"ChIJ_____y9RXTQRvnNyOkDE3vY","title":"十分老街","memo":"火車從店家門口開過去的畫面一定要拍！聽到鳴笛就退到安全線外，用廣角從鐵軌側面拍最有感。","tags":["老街","鐵道"],"lat":25.042397,"lng":121.776366},{"place_id":"ChIJxe9lrg5RXTQReSZ4lAmth-s","title":"十分放天燈","memo":"四面寫願望再放，想拍天燈升空建議用連拍或高幀率錄影。風大時店家會幫忙扶，聽老闆指示放手。","tags":["天燈","許願"],"lat":25.042669,"lng":121.776676}]},{"name":"傍晚｜九份","by":"official","items":[{"place_id":"ChIJcZT7-hdFXTQR0qekplqCFV8","title":"九份老街","memo":"日落前後燈籠亮起是最好拍的時段，豎崎路階梯人很多，早點卡位。山上天氣多變，帶件薄外套和傘。","tags":["燈籠","夜景","黃昏拍"],"lat":25.109806,"lng":121.845223}]}],"comments":[]},{"role":"friends","owner":"ex1","slug":"tokyo-osaka-5-days-with-friends","kind":"collection","title":"三人東京＋大阪五天四夜","desc":"三個人各自加想去的地方，再在留言裡吵出路線。最終行程寫在「淺草寺」的留言裡！","themes":["日本","東京","大阪","朋友旅行","自由行"],"sections":[{"name":"範例使用者1：東京經典","by":"ex1","items":[{"place_id":"ChIJ8T1GpMGOGGARDYGSgpooDWw","title":"淺草寺","memo":"第一次去東京一定要的雷門合照，仲見世通可以邊走邊吃。早上人比較少。","tags":["寺廟","經典"],"lat":35.714765,"lng":139.796655},{"place_id":"ChIJ35ov0dCOGGARKvdDH7NPHX0","title":"東京晴空塔","memo":"跟淺草寺走路或搭一站就到，可以排同一天。","tags":["展望台","地標"],"lat":35.710063,"lng":139.8107},{"place_id":"ChIJW2cLzSGLGGARXAKXv6EkbqI","title":"築地場外市場","memo":"早上去吃海鮮丼和玉子燒，很多店中午過後就收了。","tags":["早餐","海鮮"],"lat":35.66477,"lng":139.770252}]},{"name":"範例使用者2：澀谷拍照行","by":"ex2","items":[{"place_id":"ChIJK9EM68qLGGARacmu4KJj5SA","title":"澀谷十字路口","memo":"從車站周邊的高處往下拍人潮最壯觀，晚上霓虹燈更有感。","tags":["拍照","街景"],"lat":35.659482,"lng":139.70056},{"place_id":"ChIJ4Rr2JWiLGGARcyRSHuZ-9G8","title":"SHIBUYA SKY","memo":"頂樓露天展望台，日落時段最美但最難搶，要提早上網訂票。","tags":["展望台","日落"],"lat":35.658672,"lng":139.701985},{"place_id":"ChIJ5SZMmreMGGARcz8QSTiJyo8","title":"明治神宮","memo":"在原宿站旁邊，參道很長很安靜，適合早上散步。","tags":["神社","散步"],"lat":35.676398,"lng":139.699326},{"place_id":"ChIJSeco5wiJGGARItbTS8lQ5G0","title":"teamLab Planets","memo":"要赤腳走進水裡的沉浸式展，超好拍！必須事先線上買指定時段的票。","tags":["展覽","拍照"],"lat":35.649121,"lng":139.789774}]},{"name":"範例使用者3：大阪吃到飽","by":"ex3","items":[{"place_id":"ChIJg2DcJhXnAGARCbeAHoZrPeQ","title":"道頓堀","memo":"固力果跑跑人看板＋章魚燒、大阪燒，晚上最熱鬧。","tags":["美食","夜晚"],"lat":34.668647,"lng":135.503098},{"place_id":"ChIJXSJB5UHnAGARQcEjvngsHaw","title":"黑門市場","memo":"海鮮、和牛串、水果都有，早點去選擇比較多。","tags":["市場","邊走邊吃"],"lat":34.665351,"lng":135.506242},{"place_id":"ChIJ_TooXM3gAGARQR6hXH3QAQ8","title":"大阪城","memo":"公園很大，春天賞櫻、秋天看紅葉都很漂亮。","tags":["城堡","公園"],"lat":34.687257,"lng":135.525855},{"place_id":"ChIJXeLVg9DgAGARqlIyMCX-BTY","title":"日本環球影城","memo":"超級任天堂世界一定要去！建議排一整天。","tags":["樂園","一整天"],"lat":34.665677,"lng":135.432319}]}],"comments":[{"place_id":"ChIJSeco5wiJGGARItbTS8lQ5G0","by":"ex2","body":"teamLab 票是指定時段的，我們要先決定哪天去我才能訂～築地吃完直接過去如何？都在東邊。","replies":[{"by":"ex1","body":"可以！築地早上吃完搭車過去不用多久，訂上午十點多那場剛好。"},{"by":"ex3","body":"提醒一下裡面水會到小腿，那天穿可以捲起來的褲子或短褲，不然會很慘😂"}]},{"place_id":"ChIJ4Rr2JWiLGGARcyRSHuZ-9G8","by":"ex3","body":"SHIBUYA SKY 日落時段聽說很快就賣完，要不要就排在 teamLab 同一天傍晚？","replies":[{"by":"ex2","body":"好，我會盯開賣時間一起買。不過下雨的話頂樓可能會關，我們出發前看一下天氣預報。"},{"by":"ex1","body":"看完夕陽直接下樓去十字路口拍夜景，順便吃晚餐，完美。"}]},{"place_id":"ChIJXeLVg9DgAGARqlIyMCX-BTY","by":"ex3","body":"環球影城要不要買快速通關？貴是貴，但沒買的話任天堂世界可能要排超久。","replies":[{"by":"ex1","body":"預算有點超…我們只買包含任天堂世界的那種就好，其他設施早點入園慢慢排。"},{"by":"ex2","body":"同意，那天開園前就去排隊，晚餐在園區外吃比較省。"}]},{"place_id":"ChIJ5SZMmreMGGARcz8QSTiJyo8","by":"ex1","body":"第三天早上去明治神宮，然後搭新幹線去大阪，行李怎麼辦？","replies":[{"by":"ex3","body":"前一晚請飯店用宅配把大行李寄到大阪的飯店，我們只背小包移動就好。"},{"by":"ex2","body":"新幹線東京到新大阪大概兩個半小時，中午前出發，傍晚剛好殺去道頓堀吃晚餐。"}]},{"place_id":"ChIJ8T1GpMGOGGARDYGSgpooDWw","by":"ex1","body":"最終版行程！\nDay1 抵達東京→淺草寺→晴空塔看夜景\nDay2 築地早餐→teamLab Planets→SHIBUYA SKY 日落→澀谷十字路口\nDay3 明治神宮→新幹線到大阪→道頓堀\nDay4 環球影城一整天\nDay5 黑門市場早午餐→大阪城→關西機場回台灣\n東京進、大阪出的機票我來訂，大家沒問題就按讚！","replies":[{"by":"ex2","body":"讚！teamLab 和 SHIBUYA SKY 的票我負責。"},{"by":"ex3","body":"環球影城的票跟快速通關我來買，Day5 記得留時間去機場，不要逛到忘記😆"}]}]},{"role":"food","owner":"official","slug":"tainan-beef-soup-breakfast-crawl","kind":"collection","title":"台南牛肉湯早餐巡禮","desc":"台南人的早晨從一碗溫體牛肉湯開始。整理清晨開門就要排的老店、安平一帶的名店，和吃不夠時的牛肉麵備案。","themes":["台南","牛肉湯","早餐","在地美食","小吃"],"sections":[{"name":"清晨就要排隊","by":"official","items":[{"place_id":"ChIJuSIMDFR2bjQRO5xlAsCglKA","title":"六千牛肉湯","memo":"清晨開賣、賣完就收，排隊是常態。想吃到建議天一亮就到，配一碗白飯或肉燥飯。","tags":["清晨","排隊名店"],"lat":22.98922,"lng":120.194848},{"place_id":"ChIJoTun0PR2bjQRhyGcuZAEZnQ","title":"西羅殿牛肉湯","memo":"就在西羅殿廟旁，湯頭清甜，點牛肉湯配肉燥飯是經典組合。","tags":["老店","肉燥飯"],"lat":23.001528,"lng":120.207444},{"place_id":"ChIJq6qqqvd2bjQRElwKaWq_ss0","title":"旗哥牛肉湯","memo":"在地人常吃的店，除了牛肉湯，炒牛肉配白飯也很下飯。","tags":["在地","炒牛肉"],"lat":23.009832,"lng":120.185533}]},{"name":"安平一帶","by":"official","items":[{"place_id":"ChIJDXFiuxp2bjQRSldJ3YTNG8M","title":"文章牛肉湯（安平總店）","memo":"知名度最高的牛肉湯之一，觀光客多，避開用餐尖峰比較好入座。湯通常可以加，開口問店員就好。","tags":["名店","可加湯"],"lat":22.998774,"lng":120.169718},{"place_id":"ChIJv9hbKx12bjQRJmLpqLWzqsk","title":"阿財牛肉湯","memo":"在安平古堡附近，逛安平前先來一碗暖胃。沾醬用薑絲加醬油膏是台南吃法。","tags":["安平","薑絲沾醬"],"lat":22.999476,"lng":120.161475}]},{"name":"市區還想再吃","by":"official","items":[{"place_id":"ChIJ7f-bjmZ2bjQRZXmwL_jWvpQ","title":"鬍鬚忠牛肉湯","memo":"位在市區民族路上，離赤崁樓一帶不遠，適合逛古蹟前後順路吃。","tags":["市區","順路"],"lat":22.998374,"lng":120.196903},{"place_id":"ChIJy39CtpF3bjQRc8tjZ7W_n5Y","title":"豪牛牛肉湯","memo":"西門路上的人氣店，評價很高，點牛肉湯時可以選肉的部位和熟度。","tags":["人氣","西門路"],"lat":22.99808,"lng":120.199868},{"place_id":"ChIJC9c687t2bjQRBs1JpxP7Knw","title":"億哥牛肉湯","memo":"在東區，住成大、東區一帶的話很方便，湯頭偏清爽。","tags":["東區"],"lat":22.988452,"lng":120.234189},{"place_id":"ChIJPa4-cIJ3bjQRe7zQmNYgmvk","title":"老王下麵","memo":"喝膩了清湯就換一碗牛肉麵，是牛肉湯巡禮中轉換口味的好選擇。","tags":["牛肉麵","換口味"],"lat":23.001273,"lng":120.197149}]}],"comments":[]}]}$doc$::jsonb);
